// ── accessors (mirror py/parse.c npy_rule_act / get_rule_arg) ───
pub inline fn ruleAct(id: u8) u8 {
    return rule_act_table[id];
}

pub inline fn getRuleArg(id: u8) [*]const u16 {
    var off: usize = rule_arg_offset_table[id];
    if (id >= FIRST_RULE_WITH_OFFSET_ABOVE_255) off |= 0x100;
    return @ptrCast(&rule_arg_combined_table[off]);
}

// Sanity at comptime: rule_act_table / rule_arg_offset_table sizes match.
comptime {
    if (rule_act_table.len != NUM_RULES) @compileError("rule_act_table size drift");
    if (rule_arg_offset_table.len != NUM_RULES) @compileError("rule_arg_offset_table size drift");
}
